const $=id=>document.getElementById(id),premiumShelf=$("premiumShelf"),freeShelf=$("freeShelf"),details=$("bookDetails"),reader=$("bookReader"),backdrop=$("bookModalBackdrop");
function closeDetails(){details.hidden=true;if(backdrop)backdrop.hidden=true;document.body.classList.remove("modal-open")}
function openDetails(){details.hidden=false;if(backdrop)backdrop.hidden=false;document.body.classList.add("modal-open");setTimeout(()=> $("closeDetails").focus(),0)}
let activeBook=null,pages=[],pageIndex=0,fontSize=18;
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function spine(book,isPremium){const b=document.createElement("button");b.type="button";b.className="library-book "+(isPremium?"premium-book":"free-book");b.style.background=isPremium?"linear-gradient(155deg,#c4a25d,#60451e)":"linear-gradient(155deg,"+book.palette[0]+","+book.palette[1]+")";b.dataset.bookId=book.id;b.setAttribute("aria-label","Open "+book.title+" by "+(isPremium?"Taiwo A. Adekunle":"Voiceoftaade"));b.innerHTML='<span class="book-spine-publisher">Voiceoftaade</span><span class="book-spine-mark">✳</span><span class="book-spine-title">'+esc(book.title)+'</span><span class="book-spine-author">'+esc(isPremium?"Taiwo A. Adekunle":"Voiceoftaade")+'</span>';b.addEventListener("click",()=>{if(b.classList.contains("book-opening"))return;b.classList.add("book-opening");b.setAttribute("aria-busy","true");window.setTimeout(()=>{b.classList.remove("book-opening");b.removeAttribute("aria-busy");showDetails(book)},430)});return b}
premium.forEach(b=>premiumShelf.appendChild(spine(b,true)));
function renderFree(query){freeShelf.replaceChildren();const q=(query||"").toLowerCase().trim();const matches=free.filter(b=>!q||[b.title,b.description,...b.themes].join(" ").toLowerCase().includes(q));if(!matches.length){const p=document.createElement("p");p.className="shelf-no-results";p.textContent="No free titles match that search. Try love, purpose, discipline, or wisdom.";freeShelf.appendChild(p);return}for(let start=0;start<matches.length;start+=20){const row=document.createElement("div");row.className="shelf-board free-board";row.setAttribute("role","group");row.setAttribute("aria-label","Free books shelf "+(Math.floor(start/20)+1));matches.slice(start,start+20).forEach(book=>row.appendChild(spine(book,false)));freeShelf.appendChild(row)}}
renderFree("");
function showDetails(book){activeBook=book;reader.hidden=true;openDetails();const paid=book.kind==="premium",freePremium=book.kind==="premium-free";$("detailLabel").textContent=paid?"PREMIUM · PAID PUBLICATION":freePremium?"PREMIUM · FREE PUBLICATION":"FREE ORIGINAL BOOK";$("detailTitle").textContent=book.title;$("detailByline").textContent=(book.author||"Voiceoftaade")+" · Voiceoftaade Publications";$("detailDescription").textContent=book.description;$("detailThemes").innerHTML=book.themes.map(t=>'<span class="detail-chip">'+esc(t)+'</span>').join("");$("detailChapters").innerHTML=book.chapters.map(c=>'<li>'+esc(Array.isArray(c)?c[0]:c)+'</li>').join("");const art=$("detailArt");art.style.background=(paid||freePremium)?"linear-gradient(155deg,#c4a25d,#60451e)":"linear-gradient(155deg,"+book.palette[0]+","+book.palette[1]+")";art.querySelector("strong").textContent=book.title;const actions=$("detailActions");actions.replaceChildren();if(paid){const a=document.createElement("a");a.className="button button-gold";a.href=book.buy;a.textContent="View in Voiceoftaade Store ↗";actions.appendChild(a);$("detailNote").textContent="Purchase will be handled through the official Voiceoftaade Store. The early-bird offer is 40% off the ₦4,000 original price (₦2,400 for the first 21 days). Checkout remains closed until secure payment and reader-access checks are complete."}else if(freePremium){const a=document.createElement("a");a.className="button button-gold";a.href=book.read;a.textContent="Read free in the Reading Room ↗";actions.appendChild(a);$("detailNote").textContent="This title keeps its place on the premium bookshelf for its featured presentation, but the book itself is free. No purchase is required."}else{const r=document.createElement("button");r.className="button button-dark";r.type="button";r.textContent="Start reading · 31 sections";r.addEventListener("click",()=>startReading(book));actions.appendChild(r);const s=document.createElement("button");s.className="button button-outline";s.type="button";s.textContent="Share this book ↗";s.addEventListener("click",()=>shareBook(book));actions.appendChild(s);$("detailNote").textContent="Expanded free reading edition: six detailed chapters, realistic scenarios, practical exercises, reflection questions, and a final reminder to carry into daily life."} }
function buildPages(book){const out=[];book.chapters.forEach((c,i)=>{const n=i+1;out.push({title:"Chapter "+n+" · "+c[0],kind:"Story and real-life scenario",body:c[1]});out.push({title:"Chapter "+n+" · The central idea",kind:"Detailed reflection",body:c[2]});out.push({title:"Chapter "+n+" · Practical lesson",kind:"Practical application",body:c[3]});out.push({title:"Chapter "+n+" · Questions to sit with",kind:"Reflection questions",body:"Consider the chapter in the context of your life. What feels familiar? What challenges an assumption? What detail helps you see the issue differently? Think of a real situation at home, in study, at work, or in a friendship. What did you know at the time, what did you assume, and what other response was available? You do not need a perfect answer now. Write what you know, what remains uncertain, and what you want to understand more clearly.",prompt:"What honest question has this chapter helped you ask?"});out.push({title:"Chapter "+n+" · Put the idea into practice",kind:"Action page",body:"Turn the idea into one modest action that fits ordinary circumstances. Decide when it happens, what might make it difficult, and how you will adjust if the first attempt does not work. If another person is involved, be clear about what you need and remain open to their perspective. The aim is not to prove your worth through a perfect result; it is to learn from a deliberate attempt and return with better information.",prompt:"My next step is…"});});out.push({title:"Final reminder · "+book.title,kind:"Closing reflection",body:book.finalReminder||"Carry one useful lesson into your next ordinary decision. Choose a realistic action, review what happens, and allow experience to deepen your judgment.",prompt:"What is the one reminder from this book you want to practise this week?"});return out}
function startReading(book){if(book.kind==="premium")return;try{sessionStorage.setItem("voiceoftaade-reading-room-book",JSON.stringify({id:book.id,title:book.title,author:book.author||"Voiceoftaade Publications",description:book.description,chapters:book.chapters,finalReminder:book.finalReminder||""}));window.location.href="reader.html?mode=free&book="+encodeURIComponent(book.id)}catch(e){$("detailNote").textContent="The Reading Room could not open this book. Please allow this site to use session storage and try again."}}
function renderPage(){const p=pages[pageIndex];$("readerChapterTitle").textContent=p.title;$("readerPageText").innerHTML='<p class="reader-kind">'+esc(p.kind)+'</p><p>'+esc(p.body)+'</p>'+(p.prompt?'<div class="reader-prompt"><strong>Write or think about this</strong><p>'+esc(p.prompt)+'</p></div>':"");$("pageCounter").textContent="Section "+(pageIndex+1)+" of "+pages.length;$("previousPage").disabled=pageIndex===0;$("nextPage").textContent=pageIndex===pages.length-1?"Finish reading ✓":"Next →";$("readerPage").style.fontSize=fontSize+"px"}
async function shareBook(book){const url=location.href.split("#")[0]+"#"+book.id,data={title:book.title,text:"Read "+book.title+" from Voiceoftaade Publications.",url};try{if(navigator.share)await navigator.share(data);else if(navigator.clipboard){await navigator.clipboard.writeText(data.text+" "+url);alert("Book link copied. Share it with a reader.")}else prompt("Copy this book link:",url)}catch(e){if(e.name!=="AbortError")prompt("Copy this book link:",url)}}
$("shelfSearch").addEventListener("input",e=>renderFree(e.target.value));$("closeDetails").addEventListener("click",closeDetails);if(backdrop)backdrop.addEventListener("click",closeDetails);$("closeReader").addEventListener("click",()=>reader.hidden=true);document.addEventListener("keydown",e=>{if(e.key==="Escape"){if(readingModal&&!readingModal.hidden)closeReadingModal();else if(!details.hidden)closeDetails();else if(!reader.hidden)reader.hidden=true}});
$("previousPage").addEventListener("click",()=>{if(pageIndex>0){pageIndex--;renderPage();$("readerPage").scrollIntoView({behavior:"smooth",block:"start"})}});
$("nextPage").addEventListener("click",()=>{if(pageIndex<pages.length-1){pageIndex++;renderPage();$("readerPage").scrollIntoView({behavior:"smooth",block:"start"})}else{reader.hidden=true;if(activeBook)showDetails(activeBook)}});
$("fontDown").addEventListener("click",()=>{fontSize=Math.max(14,fontSize-1);renderPage()});$("fontUp").addEventListener("click",()=>{fontSize=Math.min(25,fontSize+1);renderPage()});$("backToDetails").addEventListener("click",e=>{e.preventDefault();reader.hidden=true;if(activeBook)showDetails(activeBook)});
const toggle=$("menuToggle"),nav=$("mainNav");if(toggle&&nav){toggle.addEventListener("click",()=>{const open=nav.classList.toggle("open");toggle.setAttribute("aria-expanded",String(open));toggle.textContent=open?"×":"☰"});nav.querySelectorAll("a").forEach(a=>a.addEventListener("click",()=>{if(a.classList.contains("nav-dropdown-trigger"))return;nav.classList.remove("open");toggle.setAttribute("aria-expanded","false");toggle.textContent="☰"}))}
