const readingBackdrop=$("readingModalBackdrop"),readingModal=$("readingModal"),readingContent=$("readingModalContent"),readingTitle=$("readingModalTitle"),closeReading=$("closeReadingModal");
function closeReadingModal(){if(readingModal)readingModal.hidden=true;if(readingBackdrop)readingBackdrop.hidden=true;document.body.classList.remove("reading-modal-open")}
function openReadingModal(id){const template=$("reading-template-"+id);if(!template||!readingModal||!readingContent)return;const article=template.content.querySelector("article");if(!article)return;readingTitle.textContent=article.querySelector("h2")?.textContent||"Full manuscript";readingContent.replaceChildren(article.cloneNode(true));readingModal.hidden=false;readingBackdrop.hidden=false;document.body.classList.add("reading-modal-open");if(closeReading)closeReading.focus()}
document.querySelectorAll("[data-reading-id]").forEach(button=>button.addEventListener("click",()=>openReadingModal(button.dataset.readingId)));
if(closeReading)closeReading.addEventListener("click",closeReadingModal);if(readingBackdrop)readingBackdrop.addEventListener("click",closeReadingModal);
const worksheet=$("downloadWorksheet");if(worksheet)worksheet.addEventListener("click",()=>{const text="VOICEOFTAADE PUBLICATIONS\nPERSONAL REFLECTION WORKSHEET\n\n1. What idea stood out to me today?\n\n____________________________\n\n2. What do I know for certain, and what am I assuming?\n\n____________________________\n\n3. What is one perspective I have not considered?\n\n____________________________\n\n4. What boundary or small promise would help me act with intention?\n\n____________________________\n\n5. What is one practical step I will take, and when?\n\n____________________________\n\nRead · Reflect · Live deliberately.\nVoiceoftaade Publications";const blob=new Blob([text],{type:"text/plain;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="Voiceoftaade-Reflection-Worksheet.txt";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)});
